style.css:
/* i really want this to be global */

.op-wp-single-card .op-wp-single-card--card-actions {
  left: 0;
  right: 0;
  bottom: 0;
  top: 25px!important;
}

.op-wp-single-card .op-wp-single-card--card-actions [data-test-selector="op-wp-single-card--inline-buttons"] {
  opacity: 1;
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
  box-shadow: none!important;
}

.op-wp-single-card .op-wp-single-card--card-actions [data-test-selector="op-wp-single-card--details-button"] {
  opacity: 1;
  position: absolute;
  left: 0;
  top: 0;
  right: 0;
  bottom: 0;
}
.op-wp-single-card .op-wp-single-card--card-actions [data-test-selector="op-wp-single-card--details-button"] op-icon { 
  display: none;
}

.op-wp-single-card .op-wp-single-card--content-status-baseline {
  display: none;
}

.op-wp-single-card a.op-wp-single-card--content-id {
  grid-column: 1/3!important;
}

.op-wp-single-card [data-test-selector="op-wp-single-card--content-type"] {
  text-transform: none;
  font-size: 0.85em;
}

.op-wp-single-card .op-wp-single-card--highlighting {
  bottom: 0;
  height: initial;
  right: initial;
  width: 7px;
  border: none!important;
  border-top-right-radius: 0; 
  border-bottom-left-radius: 2px;
}
